7	/**
8	 * Create-owner step: normalizes the telephone by removing every non-digit character and
9	 * requires exactly ten digits, rejecting anything else with a 400. Runs after
10	 * {@link ValidateOwnerFields} (which guarantees a non-blank value) and before
11	 * {@link BuildOwner}, mutating the published body in place so the stored and returned
12	 * telephone is the normalized ten-digit value.
13	 */
14	public class NormalizeOwnerTelephone {
15	
16	    private static final int REQUIRED_DIGITS = 10;
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
19	        String digits = digitsOnly(request.getTelephone());
20	        if (digits.length() != REQUIRED_DIGITS) {
21	            throw new InvalidTelephoneException();
22	        }
23	        request.setTelephone(digits);
24	    }
25	
26	    /** Strip every non-digit character, the shared definition of a normalized telephone. */
27	    static String digitsOnly(String telephone) {
28	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
29	    }
30	}
